<?php
declare(strict_types=1);
require_once __DIR__.'/includes/functions.php';
require_login();
$id=(int)($_GET['id']??$_POST['id']??0);$editing=$id>0;$recipe=null;$ingredients=[];$steps=[];$nutrition=null;$existingTags=[];$media=[];$errors=[];
if($editing){
 $stmt=db()->prepare('SELECT * FROM recipes WHERE id=?');$stmt->execute([$id]);$recipe=$stmt->fetch();
 if(!$recipe||((int)$recipe['author_id']!==(int)current_user()['id']&&!is_admin())){http_response_code(403);exit('You do not have permission to edit this recipe.');}
 $stmt=db()->prepare('SELECT * FROM ingredients WHERE recipe_id=? ORDER BY sort_order,id');$stmt->execute([$id]);$ingredients=$stmt->fetchAll();
 $stmt=db()->prepare('SELECT * FROM recipe_steps WHERE recipe_id=? ORDER BY step_number');$stmt->execute([$id]);$steps=$stmt->fetchAll();
 $stmt=db()->prepare('SELECT * FROM nutrition WHERE recipe_id=?');$stmt->execute([$id]);$nutrition=$stmt->fetch()?:null;
 $stmt=db()->prepare('SELECT t.name FROM tags t JOIN recipe_tags rt ON rt.tag_id=t.id WHERE rt.recipe_id=?');$stmt->execute([$id]);$existingTags=$stmt->fetchAll(PDO::FETCH_COLUMN);
 $stmt=db()->prepare('SELECT * FROM recipe_media WHERE recipe_id=? ORDER BY sort_order,id');$stmt->execute([$id]);$media=$stmt->fetchAll();
}

if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 // Media/removal controls use the same CSRF-protected editor form to avoid nested forms.
 if($editing && isset($_POST['delete_media_id'])){
   $mid=(int)$_POST['delete_media_id'];
   $stmt=db()->prepare('SELECT rm.file_path FROM recipe_media rm JOIN recipes r ON r.id=rm.recipe_id WHERE rm.id=? AND rm.recipe_id=? AND (r.author_id=? OR ?=1)');
   $stmt->execute([$mid,$id,current_user()['id'],is_admin()?1:0]);$path=$stmt->fetchColumn();
   if($path!==false){db()->prepare('DELETE FROM recipe_media WHERE id=?')->execute([$mid]);if($path){$full=__DIR__.'/'.$path;if(is_file($full)&&str_starts_with($path,'uploads/'))@unlink($full);}audit('RECIPE_MEDIA_DELETE',$id,'Media '.$mid);flash('success','Media item removed.');}
   redirect('recipe_form.php?id='.$id);
 }
 if($editing && isset($_POST['delete_recipe'])){
   db()->prepare('DELETE FROM recipes WHERE id=?')->execute([$id]);audit('RECIPE_DELETE',$id);flash('success','Recipe deleted.');redirect(is_admin()?'admin/recipes.php':'profile.php');
 }
 $title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$cuisine=trim($_POST['cuisine']??'');$category=trim($_POST['category']??'');$difficulty=$_POST['difficulty']??'Easy';$prep=max(0,(int)($_POST['prep_minutes']??0));$cook=max(0,(int)($_POST['cook_minutes']??0));$servings=max(1,(int)($_POST['servings']??1));$videoUrl=trim($_POST['video_url']??'');$tagsInput=trim($_POST['tags']??'');
 if(mb_strlen($title)<3||mb_strlen($title)>150)$errors[]='Title must be between 3 and 150 characters.';
 if(mb_strlen($description)<20||mb_strlen($description)>2000)$errors[]='Description must be between 20 and 2000 characters.';
 if($cuisine===''||mb_strlen($cuisine)>80)$errors[]='Enter a valid cuisine.';
 if($category===''||mb_strlen($category)>80)$errors[]='Enter a valid category.';
 if(!in_array($difficulty,['Easy','Medium','Hard'],true))$errors[]='Choose a valid difficulty.';
 if($prep+$cook<=0||$prep+$cook>1440)$errors[]='Enter a realistic preparation/cooking time.';
 if($servings>100)$errors[]='Servings cannot exceed 100.';
 if($videoUrl && !filter_var($videoUrl,FILTER_VALIDATE_URL))$errors[]='External video URL is invalid.';
 $ingredientNames=$_POST['ingredient_name']??[];$ingredientQty=$_POST['ingredient_qty']??[];$ingredientUnit=$_POST['ingredient_unit']??[];$ingredientNotes=$_POST['ingredient_notes']??[];
 $cleanIngredients=[];foreach($ingredientNames as $k=>$name){$name=trim((string)$name);if($name==='')continue;$cleanIngredients[]=['name'=>$name,'quantity'=>trim((string)($ingredientQty[$k]??'')),'unit'=>trim((string)($ingredientUnit[$k]??'')),'notes'=>trim((string)($ingredientNotes[$k]??''))];}
 if(count($cleanIngredients)<2)$errors[]='Add at least two ingredients.';
 $stepText=$_POST['step_instruction']??[];$cleanSteps=[];foreach($stepText as $text){$text=trim((string)$text);if($text!=='')$cleanSteps[]=$text;}if(count($cleanSteps)<2)$errors[]='Add at least two clear cooking steps.';
 $cover=null;if(!$errors){try{$cover=save_upload($_FILES['cover_image']??[],'recipes',['image/jpeg','image/png','image/webp'],5*1024*1024);}catch(Throwable $e){$errors[]=$e->getMessage();}}
 if(!$errors){
   db()->beginTransaction();
   try{
     $status=is_admin()?($_POST['status']??($recipe['status']??'approved')):'pending';
     if(!in_array($status,['pending','approved','rejected'],true))$status='pending';
     $slug=slugify($title).'-'.substr(bin2hex(random_bytes(3)),0,6);
     if($editing){
       if($cover){$stmt=db()->prepare('UPDATE recipes SET title=?,slug=?,description=?,cuisine=?,category=?,difficulty=?,prep_minutes=?,cook_minutes=?,servings=?,cover_image=?,video_url=?,status=?,updated_at=NOW() WHERE id=?');$stmt->execute([$title,$slug,$description,$cuisine,$category,$difficulty,$prep,$cook,$servings,$cover,$videoUrl?:null,$status,$id]);}
       else{$stmt=db()->prepare('UPDATE recipes SET title=?,slug=?,description=?,cuisine=?,category=?,difficulty=?,prep_minutes=?,cook_minutes=?,servings=?,video_url=?,status=?,updated_at=NOW() WHERE id=?');$stmt->execute([$title,$slug,$description,$cuisine,$category,$difficulty,$prep,$cook,$servings,$videoUrl?:null,$status,$id]);}
       $rid=$id;db()->prepare('DELETE FROM ingredients WHERE recipe_id=?')->execute([$rid]);db()->prepare('DELETE FROM recipe_steps WHERE recipe_id=?')->execute([$rid]);db()->prepare('DELETE FROM recipe_tags WHERE recipe_id=?')->execute([$rid]);db()->prepare('DELETE FROM nutrition WHERE recipe_id=?')->execute([$rid]);
     }else{
       $stmt=db()->prepare('INSERT INTO recipes(author_id,title,slug,description,cuisine,category,difficulty,prep_minutes,cook_minutes,servings,cover_image,video_url,status,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,IF(?="approved",NOW(),NULL))');$stmt->execute([current_user()['id'],$title,$slug,$description,$cuisine,$category,$difficulty,$prep,$cook,$servings,$cover,$videoUrl?:null,$status,$status]);$rid=(int)db()->lastInsertId();
     }
     $stmtI=db()->prepare('INSERT INTO ingredients(recipe_id,name,quantity,unit,notes,sort_order) VALUES(?,?,?,?,?,?)');foreach($cleanIngredients as $k=>$i)$stmtI->execute([$rid,$i['name'],$i['quantity']?:null,$i['unit']?:null,$i['notes']?:null,$k+1]);
     $stmtS=db()->prepare('INSERT INTO recipe_steps(recipe_id,step_number,instruction) VALUES(?,?,?)');foreach($cleanSteps as $k=>$text)$stmtS->execute([$rid,$k+1,$text]);
     $tagNames=array_values(array_unique(array_filter(array_map('trim',explode(',',$tagsInput)))));$stmtTag=db()->prepare('INSERT INTO tags(name) VALUES(?) ON DUPLICATE KEY UPDATE name=VALUES(name)');$stmtLink=db()->prepare('INSERT IGNORE INTO recipe_tags(recipe_id,tag_id) VALUES(?,?)');foreach($tagNames as $tag){if(mb_strlen($tag)>50)continue;$stmtTag->execute([$tag]);$stmtFind=db()->prepare('SELECT id FROM tags WHERE name=?');$stmtFind->execute([$tag]);$stmtLink->execute([$rid,(int)$stmtFind->fetchColumn()]);}
     $cal=max(0,(float)($_POST['calories_total']??0));$protein=max(0,(float)($_POST['protein_g_total']??0));$carbs=max(0,(float)($_POST['carbs_g_total']??0));$fat=max(0,(float)($_POST['fat_g_total']??0));$fibre=max(0,(float)($_POST['fibre_g_total']??0));$sodium=max(0,(float)($_POST['sodium_mg_total']??0));$nnotes=trim($_POST['nutrition_notes']??'');
     if($cal||$protein||$carbs||$fat||$fibre||$sodium){$stmtN=db()->prepare('INSERT INTO nutrition(recipe_id,calories_total,protein_g_total,carbs_g_total,fat_g_total,fibre_g_total,sodium_mg_total,notes) VALUES(?,?,?,?,?,?,?,?)');$stmtN->execute([$rid,$cal,$protein,$carbs,$fat,$fibre,$sodium,$nnotes?:null]);}
     if($videoUrl){$stmtM=db()->prepare('INSERT INTO recipe_media(recipe_id,media_type,external_url,sort_order) VALUES(?,"external_video",?,99)');if(!$editing||!array_filter($media,fn($m)=>$m['media_type']==='external_video'&&$m['external_url']===$videoUrl))$stmtM->execute([$rid,$videoUrl]);}
     // Optional multiple gallery images.
     if(isset($_FILES['gallery_images'])&&is_array($_FILES['gallery_images']['name']??null)){
       foreach($_FILES['gallery_images']['name'] as $idx=>$name){if(!$name)continue;$one=['name'=>$name,'type'=>$_FILES['gallery_images']['type'][$idx]??'','tmp_name'=>$_FILES['gallery_images']['tmp_name'][$idx]??'','error'=>$_FILES['gallery_images']['error'][$idx]??UPLOAD_ERR_NO_FILE,'size'=>$_FILES['gallery_images']['size'][$idx]??0];$path=save_upload($one,'recipes',['image/jpeg','image/png','image/webp'],5*1024*1024);if($path)db()->prepare('INSERT INTO recipe_media(recipe_id,media_type,file_path,sort_order) VALUES(?,"image",?,?)')->execute([$rid,$path,10+$idx]);}
     }
     // Optional direct video attachment (MP4/WebM, 20 MB max for the classroom prototype).
     $videoFile=save_upload($_FILES['video_file']??[],'recipes',['video/mp4','video/webm'],20*1024*1024);
     if($videoFile)db()->prepare('INSERT INTO recipe_media(recipe_id,media_type,file_path,sort_order) VALUES(?,"video",?,98)')->execute([$rid,$videoFile]);
     db()->commit();audit($editing?'RECIPE_UPDATE':'RECIPE_CREATE',$rid,'Status: '.$status);if(!is_admin()){foreach(db()->query('SELECT id FROM users WHERE role="admin" AND is_active=1')->fetchAll(PDO::FETCH_COLUMN) as $adminId)notify((int)$adminId,'moderation','Recipe “'.$title.'” is awaiting moderation.',url('admin/recipes.php'));}
     flash('success',is_admin()&&$status==='approved'?'Recipe saved and published.':'Recipe saved and sent for moderation.');redirect(is_admin()?'admin/recipes.php':'profile.php');
   }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$errors[]='The recipe could not be saved: '.$e->getMessage();}
 }
}

$form=function(string $key,string $default='')use($recipe){return $_POST[$key]??($recipe[$key]??$default);};
$ingredientRows=$_SERVER['REQUEST_METHOD']==='POST'?array_map(null,$_POST['ingredient_name']??[],$_POST['ingredient_qty']??[],$_POST['ingredient_unit']??[],$_POST['ingredient_notes']??[]):array_map(fn($x)=>[$x['name'],$x['quantity'],$x['unit'],$x['notes']],$ingredients);
if(!$ingredientRows)$ingredientRows=[['','','',''],['','','','']];
$stepRows=$_SERVER['REQUEST_METHOD']==='POST'?($_POST['step_instruction']??[]):array_column($steps,'instruction');if(!$stepRows)$stepRows=['',''];
$tagValue=$_POST['tags']??implode(', ',$existingTags);
$pageTitle=$editing?'Edit recipe':'Share a recipe';require __DIR__.'/includes/header.php';
?>
<section class="editor-head"><div class="container"><span class="eyebrow">Recipe studio</span><h1><?=$editing?'Edit your recipe':'Share something worth cooking'?></h1><p>Structured details make recipes easier to discover, follow and trust. Community submissions are reviewed before publication.</p></div></section>
<section class="section container"><form method="post" enctype="multipart/form-data" class="editor-layout" data-recipe-editor><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="editor-main"><?php if($errors):?><div class="form-errors"><strong>Please fix these items:</strong><ul><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?>
<section class="panel"><span class="step-label">01 · Basics</span><h2>Describe the recipe</h2><div class="form-grid"><label class="span-2">Recipe title<input name="title" maxlength="150" required value="<?=e((string)$form('title'))?>" placeholder="e.g. Weeknight Chicken Adobo"></label><label class="span-2">Short description<textarea name="description" maxlength="2000" rows="4" required placeholder="What makes this recipe useful or special?"><?=e((string)$form('description'))?></textarea></label><label>Cuisine<input name="cuisine" maxlength="80" required value="<?=e((string)$form('cuisine'))?>" placeholder="Filipino"></label><label>Category<input name="category" maxlength="80" required value="<?=e((string)$form('category'))?>" placeholder="Dinner"></label><label>Difficulty<select name="difficulty"><?php foreach(['Easy','Medium','Hard'] as $d):?><option <?=($form('difficulty','Easy')===$d?'selected':'')?>><?=$d?></option><?php endforeach;?></select></label><label>Servings<input type="number" name="servings" min="1" max="100" required value="<?=e((string)$form('servings','4'))?>"></label><label>Prep time (minutes)<input type="number" name="prep_minutes" min="0" max="1440" required value="<?=e((string)$form('prep_minutes','15'))?>"></label><label>Cook time (minutes)<input type="number" name="cook_minutes" min="0" max="1440" required value="<?=e((string)$form('cook_minutes','30'))?>"></label><label class="span-2">Tags <input name="tags" maxlength="300" value="<?=e($tagValue)?>" placeholder="Vegetarian, High Protein, Gluten-Free"><small>Separate tags with commas.</small></label></div></section>
<section class="panel"><span class="step-label">02 · Ingredients</span><div class="section-heading compact"><div><h2>Build the ingredient list</h2><p>Use one row per ingredient so search can discover recipes by ingredient.</p></div><button type="button" class="button button-secondary button-small" data-add-ingredient>+ Add ingredient</button></div><div data-ingredients><?php foreach($ingredientRows as $row):?><div class="repeat-row"><input name="ingredient_qty[]" value="<?=e((string)($row[1]??''))?>" placeholder="Qty e.g. 2"><input name="ingredient_unit[]" value="<?=e((string)($row[2]??''))?>" placeholder="Unit e.g. tbsp"><input name="ingredient_name[]" value="<?=e((string)($row[0]??''))?>" required placeholder="Ingredient"><input name="ingredient_notes[]" value="<?=e((string)($row[3]??''))?>" placeholder="Notes / prep"><button type="button" class="icon-button" data-remove-row aria-label="Remove ingredient">×</button></div><?php endforeach;?></div></section>
<section class="panel"><span class="step-label">03 · Method</span><div class="section-heading compact"><div><h2>Write clear steps</h2><p>Short, ordered steps are easier to follow on a phone while cooking.</p></div><button type="button" class="button button-secondary button-small" data-add-step>+ Add step</button></div><div data-steps><?php foreach($stepRows as $idx=>$text):?><div class="step-editor"><span><?=($idx+1)?></span><textarea name="step_instruction[]" rows="3" required placeholder="Describe this cooking step clearly."><?=e((string)$text)?></textarea><button type="button" class="icon-button" data-remove-row aria-label="Remove step">×</button></div><?php endforeach;?></div></section>
<section class="panel"><span class="step-label">04 · Media</span><h2>Add photos or video</h2><div class="form-grid"><label>Cover image<input type="file" name="cover_image" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP up to 5 MB.</small></label><label>Gallery images<input type="file" name="gallery_images[]" accept="image/jpeg,image/png,image/webp" multiple><small>Optional multiple images.</small></label><label>Video attachment<input type="file" name="video_file" accept="video/mp4,video/webm"><small>Optional MP4/WebM up to 20 MB.</small></label><label>External video link<input type="url" name="video_url" value="<?=e((string)$form('video_url'))?>" placeholder="https://www.youtube.com/watch?v=..."><small>Optional YouTube/Vimeo-style link.</small></label></div><?php if($media):?><h3>Manage existing media</h3><div class="media-gallery small"><?php foreach($media as $m):?><div class="media-manage"><?php if($m['media_type']==='image'&&$m['file_path']):?><img src="<?=e(url($m['file_path']))?>" alt="Existing recipe media"><?php elseif($m['media_type']==='video'&&$m['file_path']):?><video controls preload="metadata"><source src="<?=e(url($m['file_path']))?>"></video><?php else:?><div class="external-media">External video</div><?php endif;?><button class="button button-danger button-small" type="submit" name="delete_media_id" value="<?=$m['id']?>" formnovalidate>Remove</button></div><?php endforeach;?></div><?php endif;?></section>
<section class="panel"><span class="step-label">05 · Nutrition</span><h2>Nutrition totals</h2><p>Enter values for the <strong>whole recipe</strong>. CookBook automatically displays per-serving values.</p><div class="form-grid nutrition-inputs"><?php $n=$nutrition??[];foreach(['calories_total'=>'Calories (kcal)','protein_g_total'=>'Protein (g)','carbs_g_total'=>'Carbs (g)','fat_g_total'=>'Fat (g)','fibre_g_total'=>'Fibre (g)','sodium_mg_total'=>'Sodium (mg)'] as $key=>$label):?><label><?=$label?><input type="number" step="0.1" min="0" name="<?=$key?>" value="<?=e((string)($_POST[$key]??($n[$key]??'')))?>"></label><?php endforeach;?><label class="span-2">Nutrition notes<input name="nutrition_notes" maxlength="255" value="<?=e((string)($_POST['nutrition_notes']??($n['notes']??'')))?>" placeholder="Optional source or note"></label></div></section>
</div><aside class="editor-side"><div class="panel sticky-panel"><span class="eyebrow">Before submitting</span><h3>Quality checklist</h3><ul class="check-list"><li>Specific, descriptive title</li><li>Accurate preparation time</li><li>Complete ingredient quantities</li><li>Steps in logical order</li><li>Original or permitted media</li><li>No unsafe or inappropriate content</li></ul><?php if(is_admin()):?><label>Moderation status<select name="status"><option value="pending" <?=($form('status')==='pending'?'selected':'')?>>Pending</option><option value="approved" <?=($form('status')==='approved'?'selected':'')?>>Approved</option><option value="rejected" <?=($form('status')==='rejected'?'selected':'')?>>Rejected</option></select></label><?php endif;?><button class="button button-primary button-wide" type="submit"><?=$editing?'Save changes':'Submit recipe'?></button><?php if($editing):?><a class="button button-ghost button-wide" href="<?=e(url('recipe.php?id='.$id))?>">Preview recipe</a><button class="button button-danger button-wide" type="submit" name="delete_recipe" value="1" formnovalidate onclick="return confirm('Delete this recipe permanently?')">Delete recipe</button><?php endif;?></div></aside></form></section>
<template id="ingredient-template"><div class="repeat-row"><input name="ingredient_qty[]" placeholder="Qty e.g. 2"><input name="ingredient_unit[]" placeholder="Unit e.g. tbsp"><input name="ingredient_name[]" required placeholder="Ingredient"><input name="ingredient_notes[]" placeholder="Notes / prep"><button type="button" class="icon-button" data-remove-row aria-label="Remove ingredient">×</button></div></template>
<template id="step-template"><div class="step-editor"><span>1</span><textarea name="step_instruction[]" rows="3" required placeholder="Describe this cooking step clearly."></textarea><button type="button" class="icon-button" data-remove-row aria-label="Remove step">×</button></div></template>
<?php require __DIR__.'/includes/footer.php';?>
